-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.readings_progress_never_decreases()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.progress := greatest(old.progress, new.progress);
  return new;
end;
$function$;

grant execute on function public.readings_progress_never_decreases() to service_role;
